import pytest


def settings(keys: list[str], values: list[str]) -> list[str]:
    """Overlay settings on the defaults mode=fast and level=3.

    keys[i] is set to values[i]. Returns the resulting values in the order
    mode, level, then any other keys in the order they first appear in keys.
    If a key repeats, the last value given for it wins.
    Raises ValueError if keys and values differ in length.
    """
    if len(keys) != len(values):
        raise ValueError("keys and values must have the same length")
    out: dict[str, str] = {"mode": "fast", "level": "3"}
    for k, v in zip(keys, values, strict=True):
        out[k] = v
    result: list[str] = [out["mode"], out["level"]]
    for k, v in out.items():
        if k not in ("mode", "level"):
            result.append(v)
    return result


def test_defaults_when_no_overrides() -> None:
    assert settings([], []) == ["fast", "3"]


def test_override_mode_and_level() -> None:
    assert settings(["mode", "level"], ["slow", "5"]) == ["slow", "5"]


def test_override_only_level() -> None:
    assert settings(["level"], ["7"]) == ["fast", "7"]


def test_extra_keys_follow_in_given_order() -> None:
    assert settings(["color", "size"], ["red", "L"]) == ["fast", "3", "red", "L"]


def test_order_of_given_keys_does_not_reorder_defaults() -> None:
    assert settings(["level", "mode"], ["2", "safe"]) == ["safe", "2"]


def test_mixed_defaults_and_extras() -> None:
    assert settings(["color", "mode"], ["blue", "eco"]) == ["eco", "3", "blue"]


def test_repeated_extra_key_last_value_wins() -> None:
    assert settings(["color", "color"], ["red", "blue"]) == ["fast", "3", "blue"]


def test_repeated_extra_key_keeps_first_position() -> None:
    assert settings(["a", "b", "a"], ["1", "2", "3"]) == ["fast", "3", "3", "2"]


def test_length_mismatch_raises() -> None:
    with pytest.raises(ValueError):
        settings(["mode"], [])
    with pytest.raises(ValueError):
        settings([], ["fast"])
